1	/**
2	 * @module features/tv-dashboard/model/tvMath
3	 *
4	 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
5	 * delta semanal, classificação RAG, formatação compacta de moeda,
6	 * staleness e agregações determinísticas usadas pelo hook de dados.
7	 *
8	 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
9	 */
10	
11	import type {
12	  TvBusinessHours,
13	  TvCriticalItem,
14	  TvDateRange,
15	  TvException,
16	  TvExceptionsResult,
17	  TvFreshness,
18	  TvFreshnessLevel,
19	  TvPeriod,
20	  TvRagStatus,
21	  TvRecentMove,
22	  TvStockAlertItem,
23	  TvStoreWeeklyGoal,
24	  TvWeekSegment,
25	  TvWeeklyGoal,
26	} from './types';
27	
28	// ─────────────────────────────────────────────────────────────────────────────
29	// Constantes de negócio
30	// ─────────────────────────────────────────────────────────────────────────────
31	
32	/**
33	 * Janela do DIA COMERCIAL das lojas usada no pró-rata da meta (hora local):
34	 * 08:00–23:00 — lojas abrem às 8h (brunch Lago Sul) e o dia comercial fecha
35	 * às 23h (regra do CTO 2026-06-12; supersede o 10–22 do design.md §1.6
36	 * regra 5). AJUSTÁVEL: se o horário comercial mudar, basta alterar aqui —
37	 * pró-rata, "sem movimentação" e a virada do dia ({@link businessTodayIso})
38	 * derivam daqui.
39	 */
40	export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 8, end: 23 };
41	
42	/**
43	 * Janela de produção da FÁBRICA (design.md §1.6 regra 5 + §5: 06:00–18:00).
44	 * Usada TANTO no RAG da fábrica quanto no alerta visual do card.
45	 */
46	export const TV_FACTORY_HOURS: TvBusinessHours = { start: 6, end: 18 };
47	
48	/** Horas sem movimentação (dentro da janela) que tornam a LOJA âmbar. */
49	export const NO_MOVEMENT_THRESHOLD_HOURS = 3;
50	
51	/** Horas sem bipagem (na janela de produção) que tornam a FÁBRICA âmbar (§5). */
52	export const FACTORY_NO_MOVEMENT_THRESHOLD_HOURS = 2;
53	
54	/**
55	 * Ratio pró-rata (%real / %esperado, em %) abaixo do qual a venda live fica
56	 * ÂMBAR — nunca vermelho (design.md §1.6 regra 6: ratio menor que 0,75).
57	 */
58	export const LIVE_SALES_AMBER_THRESHOLD_PCT = 75;
59	
60	/** Hora local a partir da qual a regra de venda fraca passa a valer (§1.6). */
61	export const LIVE_SALES_AMBER_FROM_HOUR = 11;
62	
63	/** Máximo de linhas exibidas na faixa de exceções. */
64	export const TV_EXCEPTIONS_LIMIT = 7;
65	
66	/** Itens do mini-feed "AGORA" por coluna de unidade. */
67	export const TV_MINI_FEED_SIZE = 3;
68	
69	/** Itens de estoque crítico exibidos na coluna (lista completa no drill-down). */
70	export const TV_CRITICAL_TOP_N = 5;
71	
72	/** Máximo de linhas do feed de movimentações no drill-down por loja. */
73	export const TV_DETAIL_FEED_LIMIT = 50;
74	
75	/**
76	 * Setor canônico de `produtos_master.setor` cujos itens entram nos ALERTAS
77	 * de estoque crítico do painel (regra do CTO 2026-06-05: alertas só do setor
78	 * de produtos vendáveis — EMBALAGENS, INSUMOS, CÂMARA FRIA, ITENS COZINHA,
79	 * MERCEARIA, COMIDAS, PRODUTOS DE LIMPEZA etc. ficam FORA).
80	 *
81	 * Comparar SEMPRE por igualdade exata pós-{@link normalizeSetor} (nunca por
82	 * prefixo/ILIKE: existe o setor "PRODUTOS DE LIMPEZA") — use
83	 * {@link isTvAlertSetor}.
84	 */
85	export const TV_ALERT_SETOR = 'PRODUTOS';
86	
87	/**
88	 * ÚNICA loja cujo faturamento de PDV embute delivery (BSB Shopping): lá o
89	 * iFood/delivery passa pelo caixa Degust junto com o balcão, então o card
90	 * quebra "Loja × Delivery" (R1 da spec tv-acompanhamento-live). Nas demais
91	 * lojas o delivery NÃO entra no PDV — quebra não se aplica.
92	 *
93	 * É `lojas.id` interno (não código Degust). Constante nomeada de propósito:
94	 * exceção de NEGÓCIO documentada, não um hardcode espalhado.
95	 */
96	export const TV_DELIVERY_SPLIT_LOJA_ID = 6;
97	
98	// ─────────────────────────────────────────────────────────────────────────────
99	// Datas (helpers locais, sem dependência de timezone UTC)
100	// ─────────────────────────────────────────────────────────────────────────────
101	
102	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
103	export function toIsoDateLocal(d: Date): string {
104	  const y = d.getFullYear();
105	  const m = String(d.getMonth() + 1).padStart(2, '0');
106	  const day = String(d.getDate()).padStart(2, '0');
107	  return `${y}-${m}-${day}`;
108	}
109	
110	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
111	export function parseIsoDateLocal(iso: string): Date {
112	  const [y, m, d] = iso.split('-').map(Number);
113	  return new Date(y, (m ?? 1) - 1, d ?? 1);
114	}
115	
116	/** Soma `days` dias a uma data, retornando nova instância. */
117	export function addDays(d: Date, days: number): Date {
118	  const out = new Date(d);
119	  out.setDate(out.getDate() + days);
120	  return out;
121	}
122	
123	/**
124	 * Dia COMERCIAL corrente do painel (YYYY-MM-DD local).
125	 *
126	 * O dia comercial vai de 08h a 23h ({@link TV_BUSINESS_HOURS}): a partir
127	 * das 23h o painel VIRA para o dia seguinte — tudo zera e o novo dia
128	 * começa — então `now` com hora ≥ 23 retorna AMANHÃ. Vendas de madrugada
129	 * (00h–05h) pertencem ao caixa do dia ANTERIOR (mesma convenção de
130	 * {@link TV_OVERNIGHT_END_HOUR}/{@link businessHourRank}): nesse horário o
131	 * dia comercial corrente é o próprio dia-calendário, ainda zerado até a
132	 * abertura das 08h — os totais do dia fechado ficam acessíveis no
133	 * histórico (◀).
134	 */
135	export function businessTodayIso(now: Date): string {
136	  return now.getHours() >= TV_BUSINESS_HOURS.end
137	    ? toIsoDateLocal(addDays(now, 1))
138	    : toIsoDateLocal(now);
139	}
140	
141	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
142	export function formatLaggedDateLabel(isoDate: string): string {
143	  const d = parseIsoDateLocal(isoDate);
144	  const dd = String(d.getDate()).padStart(2, '0');
145	  const mm = String(d.getMonth() + 1).padStart(2, '0');
146	  return `até ${dd}/${mm}`;
147	}
148	
149	/**
150	 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
151	 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
152	 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
153	 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
154	 */
155	export function parseBrDateTime(value: string | null | undefined): Date | null {
156	  if (!value) return null;
157	  const m = value.match(
158	    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
159	  );
160	  if (m) {
161	    const [, dd, mm, yyyy, hh, mi, ss] = m;
162	    const month = Number(mm);
163	    const day = Number(dd);
164	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
165	    return new Date(
166	      Number(yyyy),
167	      month - 1,
168	      day,
169	      Number(hh),
170	      Number(mi),
171	      ss ? Number(ss) : 0,
172	    );
173	  }
174	  const fallback = new Date(value);
175	  return Number.isNaN(fallback.getTime()) ? null : fallback;
176	}
177	
178	/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
179	export function timeHHMMFromIso(iso: string | null | undefined): string {
180	  if (!iso) return '—';
181	  const d = new Date(iso);
182	  if (Number.isNaN(d.getTime())) return '—';
183	  const hh = String(d.getHours()).padStart(2, '0');
184	  const mm = String(d.getMinutes()).padStart(2, '0');
185	  return `${hh}:${mm}`;
186	}
187	
188	// ─────────────────────────────────────────────────────────────────────────────
189	// Ranges do filtro global de período (v3) — datas LOCAIS, puras e testáveis
190	// ─────────────────────────────────────────────────────────────────────────────
191	
192	/**
193	 * Range do filtro global (fechado [from, to], YYYY-MM-DD local):
194	 * - `today`: hoje → hoje;
195	 * - `week`: segunda-feira da semana corrente → hoje;
196	 * - `month`: dia 1º do mês corrente → hoje.
197	 */
198	export function periodRange(period: TvPeriod, now: Date): TvDateRange {
199	  const today = toIsoDateLocal(now);
200	  if (period === 'today') return { from: today, to: today };
201	  if (period === 'week') {
202	    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
203	    const dowFromMonday = (now.getDay() + 6) % 7;
204	    const monday = addDays(now, -dowFromMonday);
205	    return { from: toIsoDateLocal(monday), to: today };
206	  }
207	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
208	  return { from: toIsoDateLocal(firstOfMonth), to: today };
209	}
210	
211	/**
212	 * Período ANTERIOR equivalente para comparativos do filtro global:
213	 * - `today`: ontem → ontem;
214	 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
215	 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
216	 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
217	 */
218	export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
219	  if (period === 'today') {
220	    const yesterday = toIsoDateLocal(addDays(now, -1));
221	    return { from: yesterday, to: yesterday };
222	  }
223	  if (period === 'week') {
224	    const dowFromMonday = (now.getDay() + 6) % 7;
225	    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
226	    return {
227	      from: toIsoDateLocal(mondayLastWeek),
228	      to: toIsoDateLocal(addDays(now, -7)),
229	    };
230	  }
231	  const y = now.getFullYear();
232	  const m = now.getMonth();
233	  const firstPrev = new Date(y, m - 1, 1);
234	  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
235	  const lastDayPrevMonth = new Date(y, m, 0).getDate();
236	  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
237	  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
238	}
239	
240	/**
241	 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
242	 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
243	 */
244	export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
245	  const from = parseIsoDateLocal(range.from);
246	  const to = parseIsoDateLocal(range.to);
247	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
248	  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
249	  return {
250	    from: toIsoDateLocal(addDays(from, -days)),
251	    to: toIsoDateLocal(addDays(to, -days)),
252	  };
253	}
254	
255	/**
256	 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
257	 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
258	 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
259	 * (exclusivo — usar `.lt`, nunca `.lte`).
260	 */
261	export function rangeToLocalDayBounds(range: TvDateRange): {
262	  startIso: string;
263	  endExclusiveIso: string;
264	} {
265	  const start = parseIsoDateLocal(range.from);
266	  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
267	  return {
268	    startIso: start.toISOString(),
269	    endExclusiveIso: endExclusive.toISOString(),
270	  };
271	}
272	
273	/**
274	 * Range do filtro global DESLOCADO `offset` períodos no tempo (R2 —
275	 * histórico navegável). Offset 0 = comportamento de {@link periodRange}
276	 * (período corrente, parcial até hoje). Offset −n = período PASSADO
277	 * COMPLETO n posições atrás:
278	 * - `today`: o dia inteiro n dias atrás;
279	 * - `week`: a semana seg-dom COMPLETA n semanas atrás;
280	 * - `month`: o mês-calendário COMPLETO n meses atrás.
281	 *
282	 * Offset positivo não é suportado (não há futuro a navegar) — tratado
283	 * como 0 por segurança.
284	 */
285	export function shiftedPeriodRange(
286	  period: TvPeriod,
287	  offset: number,
288	  now: Date,
289	): TvDateRange {
290	  if (offset >= 0) return periodRange(period, now);
291	  if (period === 'today') {
292	    const day = toIsoDateLocal(addDays(now, offset));
293	    return { from: day, to: day };
294	  }
295	  if (period === 'week') {
296	    const dowFromMonday = (now.getDay() + 6) % 7;
297	    const monday = addDays(now, -dowFromMonday + offset * 7);
298	    return { from: toIsoDateLocal(monday), to: toIsoDateLocal(addDays(monday, 6)) };
299	  }
300	  const first = new Date(now.getFullYear(), now.getMonth() + offset, 1);
301	  // `new Date(y, m+1, 0)` = último dia do mês `m`
302	  const last = new Date(now.getFullYear(), now.getMonth() + offset + 1, 0);
303	  return { from: toIsoDateLocal(first), to: toIsoDateLocal(last) };
304	}
305	
306	// ─────────────────────────────────────────────────────────────────────────────
307	// Meta mensal — semanas seg-dom recortadas ao mês + redistribuição (R4)
308	// ─────────────────────────────────────────────────────────────────────────────
309	
310	/**
311	 * Segmentos seg-dom de um mês, RECORTADOS aos limites do mês: o primeiro
312	 * e o último podem ter menos de 7 dias (mês que começa/termina no meio da
313	 * semana). `index` é 1-based ("Semana 1").
314	 *
315	 * @param year - Ano (ex.: 2026).
316	 * @param monthIndex0 - Mês 0-based (convenção JS `Date.getMonth()`).
317	 */
318	export function monthWeekSegments(
319	  year: number,
320	  monthIndex0: number,
321	): TvWeekSegment[] {
322	  const lastDay = new Date(year, monthIndex0 + 1, 0).getDate();
323	  const segments: TvWeekSegment[] = [];
324	  let day = 1;
325	  let index = 1;
326	  while (day <= lastDay) {
327	    const start = new Date(year, monthIndex0, day);
328	    const dowFromMonday = (start.getDay() + 6) % 7;
329	    const endDay = Math.min(day + (6 - dowFromMonday), lastDay);
330	    segments.push({
331	      index,
332	      from: toIsoDateLocal(start),
333	      to: toIsoDateLocal(new Date(year, monthIndex0, endDay)),
334	      days: endDay - day + 1,
335	    });
336	    day = endDay + 1;
337	    index += 1;
338	  }
339	  return segments;
340	}
341	
342	/**
343	 * Metas semanais do mês de `now` com REDISTRIBUIÇÃO iterativa da meta
344	 * mensal (que é fixa): para cada segmento, em ordem,
345	 * `target = (metaMensal − comprometido) × dias do segmento ÷ dias restantes`,
346	 * onde "comprometido" acumula o REALIZADO das semanas já encerradas e o
347	 * TARGET das semanas correntes/futuras (assume on-target dali em diante).
348	 *
349	 * Consequências (A4 da spec):
350	 * - semana que não bate a meta ⇒ targets das seguintes SOBEM;
351	 * - semana que supera ⇒ targets das seguintes DESCEM;
352	 * - invariante: realizado das semanas passadas + soma dos targets
353	 *   restantes = metaMensal, sempre (targets podem ficar negativos se o
354	 *   realizado já passou da meta — honesto, sem clamp).
355	 *
356	 * `achieved` = soma de `realizadoPorDia` nos dias do segmento (semanas
357	 * passadas e corrente); null para semanas futuras (sem dados ainda).
358	 */
359	export function weeklyTargets(
360	  metaMensal: number,
361	  realizadoPorDia: Map<string, number>,
362	  now: Date,
363	): TvWeeklyGoal[] {
364	  const segments = monthWeekSegments(now.getFullYear(), now.getMonth());
365	  const todayIso = toIsoDateLocal(now);
366	  const sumSegment = (seg: TvWeekSegment): number => {
367	    let sum = 0;
368	    let d = parseIsoDateLocal(seg.from);
369	    for (let i = 0; i < seg.days; i += 1) {
370	      sum += realizadoPorDia.get(toIsoDateLocal(d)) ?? 0;
371	      d = addDays(d, 1);
372	    }
373	    return sum;
374	  };
375	
376	  let committed = 0;
377	  let daysRemaining = segments.reduce((s, seg) => s + seg.days, 0);
378	  const out: TvWeeklyGoal[] = [];
379	  for (const seg of segments) {
380	    const target =
381	      daysRemaining > 0 ? ((metaMensal - committed) * seg.days) / daysRemaining : 0;
382	    const isPast = seg.to < todayIso;
383	    const isCurrent = seg.from <= todayIso && todayIso <= seg.to;
384	    const achieved = isPast || isCurrent ? sumSegment(seg) : null;
385	    out.push({ segment: seg, target, achieved, isCurrent });
386	    // Passadas comprometem o REAL (déficit/superávit redistribui);
387	    // corrente/futuras comprometem o TARGET (projeção on-target).
388	    committed += isPast ? (achieved ?? 0) : target;
389	    daysRemaining -= seg.days;
390	  }
391	  return out;
392	}
393	
394	/**
395	 * Meta semanal de UMA loja na SEMANA CORRENTE: aplica {@link weeklyTargets}
396	 * (mesma redistribuição da meta mensal usada no monthProgress da rede) ao
397	 * realizado diário da loja e extrai o segmento corrente.
398	 *
399	 * - `target` = meta redistribuída da semana corrente (semana 1 abaixo da
400	 *   meta ⇒ target sobe; acima ⇒ desce);
401	 * - `achieved` = soma do realizado nos dias do segmento corrente (segunda →
402	 *   agora — dias futuros não têm entrada no mapa e contam 0);
403	 * - `pct` = achieved/target × 100, null se target ≤ 0 (sem % honesto).
404	 *
405	 * Retorna null quando não há meta mensal positiva cadastrada ou quando
406	 * `now` está fora de qualquer segmento do mês (não acontece na prática).
407	 */
408	export function currentWeekGoal(
409	  metaMensal: number | null | undefined,
410	  realizadoPorDia: Map<string, number>,
411	  now: Date,
412	): TvStoreWeeklyGoal | null {
413	  if (metaMensal == null || metaMensal <= 0) return null;
414	  const current = weeklyTargets(metaMensal, realizadoPorDia, now).find(
415	    (w) => w.isCurrent,
416	  );
417	  if (!current) return null;
418	  const achieved = current.achieved ?? 0;
419	  return {
420	    target: current.target,
421	    achieved,
422	    pct: current.target > 0 ? (achieved / current.target) * 100 : null,
423	  };
424	}
425	
426	/**
427	 * Fração ESPERADA da semana corrente já decorrida em `now` — análoga ao
428	 * `expectedMonthPct` da barra mensal (dias inteiros; HOJE conta inteiro,
429	 * mesmo padrão de `now.getDate() / daysInMonth`). A "semana" é o segmento
430	 * seg-dom do mês CORRENTE recortado por {@link monthWeekSegments} (mesmo
431	 * recorte de {@link weeklyTargets}/{@link currentWeekGoal}).
432	 *
433	 * Uso: pace-ajustar a COR da meta semanal (`ratio = %real / %esperado`),
434	 * consistente com a barra mensal — começo de semana no ritmo NÃO fica
435	 * vermelho. O % numérico exibido segue sendo o real (achieved/target).
436	 *
437	 * Retorna 1 se `now` não cair em nenhum segmento (defensivo — na prática
438	 * todo dia do mês pertence a um segmento).
439	 */
440	export function expectedWeekFraction(now: Date): number {
441	  const todayIso = toIsoDateLocal(now);
442	  const segment = monthWeekSegments(now.getFullYear(), now.getMonth()).find(
443	    (s) => s.from <= todayIso && todayIso <= s.to,
444	  );
445	  if (!segment) return 1;
446	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas)
447	  const elapsedDays =
448	    Math.round(
449	      (parseIsoDateLocal(todayIso).getTime() -
450	        parseIsoDateLocal(segment.from).getTime()) /
451	        86_400_000,
452	    ) + 1;
453	  return Math.min(1, elapsedDays / segment.days);
454	}
455	
456	// ─────────────────────────────────────────────────────────────────────────────
457	// Curva horária (R5) + projeção de fim de mês (R3)
458	// ─────────────────────────────────────────────────────────────────────────────
459	
460	/**
461	 * Hora-limite da madrugada no DIA COMERCIAL: buckets 00h–05h pertencem ao
462	 * FIM do dia, não ao começo. O caixa do Degust agrupa por dataCaixa — uma
463	 * venda às 02:00 tem dataCaixa do dia anterior (é o fechamento da noite),
464	 * então na curva horária ela vem DEPOIS das 23h, nunca antes da manhã.
465	 *
466	 * NÃO atrelar este corte a {@link TV_BUSINESS_HOURS}.start: a abertura
467	 * comercial (08h — brunch Lago Sul vende com chaves reais "08"/"09" no
468	 * byHour) é regra de meta/pró-rata; este corte só separa madrugada de
469	 * manhã na curva horária — 06h é seguro abaixo de qualquer abertura real.
470	 */
471	export const TV_OVERNIGHT_END_HOUR = 6;
472	
473	/**
474	 * Rank de uma hora-calendário dentro do DIA COMERCIAL: madrugada (00–05)
475	 * desloca +24 para ordenar DEPOIS das 23h. Sequência resultante:
476	 * 06, 07, …, 23, 24 (=00h), 25 (=01h), …, 29 (=05h).
477	 */
478	export function businessHourRank(hour: number): number {
479	  return hour < TV_OVERNIGHT_END_HOUR ? hour + 24 : hour;
480	}
481	
482	/**
483	 * Base "ontem até a MESMA hora" usando a curva horária REAL do dia de
484	 * referência: `prevDayTotal` × fração, onde fração = cumulativo de
485	 * `prevDayByHour` até HH:mm ÷ cumulativo total. A hora corrente entra com
486	 * fração linear do minuto dentro da hora (15:30 → metade do bucket "15").
487	 *
488	 * A curva é usada APENAS como fração (kits têm valorUnitario 0 na fonte) —
489	 * o valor absoluto vem sempre do total oficial `prevDayTotal`.
490	 *
491	 * O cumulativo segue a ordem do DIA COMERCIAL ({@link businessHourRank}):
492	 * buckets da madrugada (00h–05h, dataCaixa do dia anterior — fechamento da
493	 * noite) ordenam DEPOIS das 23h, e a hora corrente também é ranqueada —
494	 * às 00:30 o ponto de corte é 24,5 (fim do dia comercial corrente), não
495	 * 0,5. Sem isso, uma venda às 02h de ontem inflava a base da MANHÃ de hoje.
496	 *
497	 * Retorna null quando não há base honesta — curva ausente/vazia, cumulativo
498	 * total 0, total não positivo ou fração 0 (antes da 1ª venda do dia de
499	 * referência) — para o caller cair no fallback pró-rata linear existente.
500	 */
501	export function hourlyPaceBase(
502	  prevDayTotal: number,
503	  prevDayByHour: Record<string, number> | undefined,
504	  now: Date,
505	): number | null {
506	  if (prevDayTotal <= 0 || !prevDayByHour) return null;
507	  const buckets: Array<[number, number]> = [];
508	  for (const [hh, value] of Object.entries(prevDayByHour)) {
509	    const hour = Number(hh);
510	    if (!Number.isInteger(hour) || hour < 0 || hour > 23) continue;
511	    buckets.push([businessHourRank(hour), value]);
512	  }
513	  const cumTotal = buckets.reduce((s, [, v]) => s + v, 0);
514	  if (cumTotal <= 0) return null;
515	  const currentRank = businessHourRank(now.getHours());
516	  const minuteFraction = (now.getMinutes() + now.getSeconds() / 60) / 60;
517	  let cumNow = 0;
518	  for (const [rank, value] of buckets) {
519	    if (rank < currentRank) cumNow += value;
520	    else if (rank === currentRank) cumNow += value * minuteFraction;
521	  }
522	  if (cumNow <= 0) return null;
523	  return prevDayTotal * (cumNow / cumTotal);
524	}
525	
526	/**
527	 * Projeção de fim de mês por run-rate (mtd ÷ dias decorridos × dias do
528	 * mês), com "dias decorridos" = dias COMPLETOS decorridos + 1 (hoje conta
529	 * inteiro — sem fração de dia, decisão da spec). No dia 1º a projeção é
530	 * o run-rate de 1 dia (`mtd × diasDoMês`).
531	 */
532	export function monthEndProjection(mtdTotal: number, now: Date): number {
533	  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
534	  const daysElapsed = now.getDate();
535	  return (mtdTotal / daysElapsed) * daysInMonth;
536	}
