538	// ─────────────────────────────────────────────────────────────────────────────
539	// Pró-rata da meta
540	// ─────────────────────────────────────────────────────────────────────────────
541	
542	/**
543	 * Fração linear do dia comercial já decorrida em `now`.
544	 *
545	 * - Antes da abertura → 0 (não há venda esperada ainda).
546	 * - Depois do fechamento → 1 (meta integral esperada).
547	 * - Dentro da janela → interpolação linear simples (pró-rata).
548	 */
549	export function businessDayFraction(
550	  now: Date,
551	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
552	): number {
553	  const { start, end } = hours;
554	  if (end <= start) {
555	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
556	    return now.getHours() >= end ? 1 : 0;
557	  }
558	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
559	  if (h <= start) return 0;
560	  if (h >= end) return 1;
561	  return (h - start) / (end - start);
562	}
563	
564	/**
565	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
566	 *
567	 * Retorna null quando não dá para calcular com honestidade:
568	 * - meta ausente/zerada (sem referência), ou
569	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
570	 */
571	export function pctOfProRataTarget(
572	  sold: number,
573	  dailyTarget: number | null | undefined,
574	  now: Date,
575	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
576	): number | null {
577	  if (dailyTarget == null || dailyTarget <= 0) return null;
578	  const fraction = businessDayFraction(now, hours);
579	  if (fraction <= 0) return null;
580	  return (sold / (dailyTarget * fraction)) * 100;
581	}
582	
583	/**
584	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
585	 * cujo dia de referência já encerrou.
586	 */
587	export function pctOfFullDayTarget(
588	  sold: number,
589	  dailyTarget: number | null | undefined,
590	): number | null {
591	  if (dailyTarget == null || dailyTarget <= 0) return null;
592	  return (sold / dailyTarget) * 100;
593	}
