595	// ─────────────────────────────────────────────────────────────────────────────
596	// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
597	// ─────────────────────────────────────────────────────────────────────────────
598	
599	/**
600	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
601	 * passada, período anterior do filtro…). Retorna null quando a base é
602	 * ausente ou não positiva — sem base honesta, sem número inventado.
603	 */
604	export function relativeDelta(
605	  current: number,
606	  base: number | null | undefined,
607	): number | null {
608	  if (base == null || base <= 0) return null;
609	  return ((current - base) / base) * 100;
610	}
611	
612	/**
613	 * Delta % vs MESMO DIA da semana anterior — caso particular de
614	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
615	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
616	 */
617	export function weekOverWeekDelta(
618	  current: number,
619	  lastWeek: number | null | undefined,
620	): number | null {
621	  return relativeDelta(current, lastWeek);
622	}
623	
624	/**
625	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
626	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
627	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
628	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
629	 * usada no pró-rata da meta, por consistência).
630	 *
631	 * Comparar dia parcial com dia completo inflava a queda de manhã.
632	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
633	 *
634	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
635	 * (fração 0 — não há ponto de comparação honesto).
636	 */
637	export function proRataDayBase(
638	  referenceDayTotal: number | null | undefined,
639	  now: Date,
640	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
641	): number | null {
642	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
643	  const fraction = businessDayFraction(now, hours);
644	  if (fraction <= 0) return null;
645	  return referenceDayTotal * fraction;
646	}
647	
648	/**
649	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
650	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
651	 * a API existente).
652	 */
653	export function proRataLastWeekBase(
654	  lastWeek: number | null | undefined,
655	  now: Date,
656	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
657	): number | null {
658	  return proRataDayBase(lastWeek, now, hours);
659	}
