662	// RAG da loja
663	// ─────────────────────────────────────────────────────────────────────────────
664	
665	/** Entrada da classificação RAG de uma unidade. */
666	export interface StoreRagInput {
667	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
668	  stockOutCount: number;
669	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
670	  stockLowCount: number;
671	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
672	  pctMetaProRata: number | null;
673	  /** true quando a unidade tem venda ao vivo (canal Degust). */
674	  isLiveChannel: boolean;
675	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
676	  lastMovementAt: Date | string | null;
677	  /** Instante da avaliação. */
678	  now: Date;
679	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
680	  hours?: TvBusinessHours;
681	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
682	  noMovementThresholdHours?: number;
683	}
684	
685	/**
686	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
687	 *
688	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
689	 *   não faz sentido alertar madrugada sem bipagem.
690	 * - A referência é clampada ao início da janela de hoje: se a última
691	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
692	 */
693	export function hoursWithoutMovementInWindow(
694	  lastMovementAt: Date | string | null,
695	  now: Date,
696	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
697	): number | null {
698	  const fraction = businessDayFraction(now, hours);
699	  if (fraction <= 0 || fraction >= 1) return null;
700	  const windowStart = new Date(now);
701	  windowStart.setHours(hours.start, 0, 0, 0);
702	  const last = lastMovementAt
703	    ? new Date(lastMovementAt).getTime()
704	    : Number.NEGATIVE_INFINITY;
705	  const ref = Math.max(last, windowStart.getTime());
706	  return (now.getTime() - ref) / 3_600_000;
707	}
708	
709	/**
710	 * Classificação RAG de uma unidade (management-by-exception).
711	 *
712	 * Regras (design.md §1.6, ordem de precedência):
713	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
714	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
715	 *   manhã, quando o pró-rata ainda é instável).
716	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
717	 *   movimentação há mais que o threshold dentro da janela OU venda live com
718	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
719	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
720	 *   em canal live e com meta cadastrada (pct != null).
721	 * - OK: nenhum desvio — tela calma, sem cor.
722	 */
723	export function classifyStoreRag(input: StoreRagInput): {
724	  status: TvRagStatus;
725	  reasons: string[];
726	} {
727	  const hours = input.hours ?? TV_BUSINESS_HOURS;
728	  const noMovementThreshold =
729	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
730	  const reasons: string[] = [];
731	
732	  // ── Vermelho: só ruptura (item zerado em alerta) ──
733	  if (input.stockOutCount > 0) {
734	    reasons.push(
735	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
736	    );
737	    return { status: 'red', reasons };
738	  }
739	
740	  // ── Âmbar ──
741	  if (input.stockLowCount > 0) {
742	    reasons.push(
743	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
744	    );
745	  }
746	  const gapHours = hoursWithoutMovementInWindow(
747	    input.lastMovementAt,
748	    input.now,
749	    hours,
750	  );
751	  if (gapHours !== null && gapHours > noMovementThreshold) {
752	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
753	  }
754	  if (
755	    input.isLiveChannel &&
756	    input.pctMetaProRata !== null &&
757	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
758	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
759	  ) {
760	    reasons.push(
761	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
762	    );
763	  }
764	  if (reasons.length > 0) return { status: 'amber', reasons };
765	
766	  return { status: 'ok', reasons: [] };
767	}
768	
769	/** Entrada de {@link buildNoMovementException}. */
770	export interface NoMovementExceptionInput {
771	  lojaId: number;
772	  lojaNome: string;
773	  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
774	  lastMovementAt: Date | string | null;
775	  now: Date;
776	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
777	  hours?: TvBusinessHours;
778	  /** Threshold em horas (default lojas 3h; fábrica 2h). */
779	  thresholdHours?: number;
780	}
781	
782	/**
783	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
784	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
785	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
786	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
787	 * Retorna null quando não há gap acima do threshold dentro da janela.
788	 */
789	export function buildNoMovementException(
790	  input: NoMovementExceptionInput,
791	): TvException | null {
792	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
793	  const gap = hoursWithoutMovementInWindow(
794	    input.lastMovementAt,
795	    input.now,
796	    input.hours ?? TV_BUSINESS_HOURS,
797	  );
798	  if (gap === null || gap <= threshold) return null;
799	  return {
800	    id: `no-movement:${input.lojaId}`,
801	    kind: 'no-movement',
802	    severity: 'amber',
803	    lojaId: input.lojaId,
804	    lojaNome: input.lojaNome,
805	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
806	  };
807	}
