809	// ─────────────────────────────────────────────────────────────────────────────
810	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
811	// ─────────────────────────────────────────────────────────────────────────────
812	
813	function trimOneDecimal(v: number): string {
814	  const rounded = Math.round(v * 10) / 10;
815	  return rounded.toLocaleString('pt-BR', {
816	    minimumFractionDigits: 0,
817	    maximumFractionDigits: 1,
818	  });
819	}
820	
821	/**
822	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
823	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
824	 * Valores negativos preservam o sinal ("-R$ 1,2k").
825	 */
826	export function formatCompactBRL(value: number): string {
827	  const sign = value < 0 ? '-' : '';
828	  const abs = Math.abs(value);
829	  // Bump pra M quando o arredondamento em k chegaria a 1000k
830	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
831	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
832	  }
833	  if (abs >= 1_000) {
834	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
835	  }
836	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
837	}
838	
839	// ─────────────────────────────────────────────────────────────────────────────
840	// Staleness
841	// ─────────────────────────────────────────────────────────────────────────────
842	
843	/**
844	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
845	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
846	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
847	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
848	 */
849	export function classifyStaleness(
850	  lastUpdatedAt: Date | string | number | null | undefined,
851	  expectedIntervalMs: number,
852	  now: Date,
853	): TvFreshnessLevel {
854	  if (lastUpdatedAt == null) return 'very-stale';
855	  const ts = new Date(lastUpdatedAt).getTime();
856	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
857	  const age = now.getTime() - ts;
858	  if (age < 2 * expectedIntervalMs) return 'fresh';
859	  if (age < 6 * expectedIntervalMs) return 'stale';
860	  return 'very-stale';
861	}
862	
863	/**
864	 * Monta o freshness consolidado a partir dos timestamps CRUS de última
865	 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
866	 *
867	 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
868	 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
869	 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
870	 * parar de avançar além de 2× o intervalo esperado.
871	 */
872	export function buildFreshness(
873	  liveUpdatedAtMs: number,
874	  stockUpdatedAtMs: number,
875	  intervals: { liveMs: number; slowMs: number },
876	  now: Date,
877	): TvFreshness {
878	  const liveUpdatedAt =
879	    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
880	  const stockUpdatedAt =
881	    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
882	  return {
883	    vendasLive: {
884	      updatedAt: liveUpdatedAt,
885	      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
886	      expectedIntervalMs: intervals.liveMs,
887	    },
888	    estoque: {
889	      updatedAt: stockUpdatedAt,
890	      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
891	      expectedIntervalMs: intervals.slowMs,
892	    },
893	    geradoEm: now.toISOString(),
894	  };
895	}
