897	// ─────────────────────────────────────────────────────────────────────────────
898	// Exceções — ordenação e corte
899	// ─────────────────────────────────────────────────────────────────────────────
900	
901	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
902	// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
903	const KIND_ORDER: Record<string, number> = {
904	  'stock-out': 0,
905	  'stock-low': 1,
906	  'no-movement': 2,
907	  'stale-data': 3,
908	};
909	
910	/**
911	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
912	 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
913	 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
914	 * contagem do excedente.
915	 */
916	export function sortAndLimitExceptions(
917	  exceptions: TvException[],
918	  limit: number = TV_EXCEPTIONS_LIMIT,
919	): TvExceptionsResult {
920	  const sorted = [...exceptions].sort((a, b) => {
921	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
922	    if (sev !== 0) return sev;
923	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
924	    if (kind !== 0) return kind;
925	    return a.message.localeCompare(b.message, 'pt-BR');
926	  });
927	  return {
928	    items: sorted.slice(0, limit),
929	    overflowCount: Math.max(0, sorted.length - limit),
930	    totalCount: sorted.length,
931	  };
932	}
