935	// Agregações determinísticas usadas pelo hook (puras, testáveis)
936	// ─────────────────────────────────────────────────────────────────────────────
937	
938	/** Linha mínima de `movimentacoes` necessária à agregação. */
939	export interface MovementRow {
940	  loja_id: number | null;
941	  tipo_movimentacao: string;
942	  data_movimentacao: string | null;
943	}
944	
945	/** Resultado por loja da agregação de movimentações do dia. */
946	export interface MovementAggregate {
947	  entradas: number;
948	  saidas: number;
949	  ultimaBipagem: string | null;
950	}
951	
952	/**
953	 * Agrega movimentações do dia por loja: contagem de entradas, saídas e
954	 * timestamp da última movimentação ("última bipagem"). Linhas sem loja
955	 * são ignoradas.
956	 */
957	export function aggregateMovements(
958	  rows: MovementRow[],
959	): Map<number, MovementAggregate> {
960	  const out = new Map<number, MovementAggregate>();
961	  for (const row of rows) {
962	    if (row.loja_id == null) continue;
963	    let agg = out.get(row.loja_id);
964	    if (!agg) {
965	      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
966	      out.set(row.loja_id, agg);
967	    }
968	    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
969	    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
970	    if (
971	      row.data_movimentacao &&
972	      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
973	    ) {
974	      agg.ultimaBipagem = row.data_movimentacao;
975	    }
976	  }
977	  return out;
978	}
