980	/**
981	 * Normaliza um valor de `produtos_master.setor` para comparação: trim,
982	 * minúsculas e remoção de acentos (NFD). O banco tem caixa/acentuação
983	 * inconsistentes no MESMO setor (ex.: "CÂMARA FRIA" e "Câmara Fria") —
984	 * toda comparação de setor DEVE passar por aqui.
985	 */
986	export function normalizeSetor(value: string | null | undefined): string {
987	  return (value ?? '')
988	    .normalize('NFD')
989	    .replace(/\p{M}/gu, '')
990	    .trim()
991	    .toLowerCase();
992	}
993	
994	/**
995	 * true quando o setor é o {@link TV_ALERT_SETOR} (igualdade EXATA após
996	 * {@link normalizeSetor} — nunca prefixo: "PRODUTOS DE LIMPEZA" NÃO conta).
997	 */
998	export function isTvAlertSetor(setor: string | null | undefined): boolean {
999	  return normalizeSetor(setor) === normalizeSetor(TV_ALERT_SETOR);
1000	}
