1030	  const out = new Map<number, StockDetail>();
1031	  for (const row of rows) {
1032	    if (row.loja_id == null) continue;
1033	    if (!isTvAlertSetor(row.setor)) continue; // fora do setor vendável → sem alerta
1034	    const min = row.quantidade_minima ?? 0;
1035	    if (min <= 0) continue; // sem mínimo definido → sem alerta
1036	    const qty = row.quantidade_atual ?? 0;
1037	    if (qty >= min) continue; // dentro do normal
1038	    let detail = out.get(row.loja_id);
1039	    if (!detail) {
1040	      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
1041	      out.set(row.loja_id, detail);
1042	    }
1043	    const zerado = qty <= 0;
1044	    if (zerado) detail.zerados += 1;
1045	    else detail.abaixoMinimo += 1;
1046	    detail.itens.push({
1047	      produtoNome: row.produtoNome,
1048	      quantidade: qty,
1049	      quantidadeMinima: min,
1050	      zerado,
1051	    });
1052	  }
