1110	export function remapFlashLojaIds(
1111	  rows: FlashRow[],
1112	  degustCodeToLoja: ReadonlyMap<number, number>,
1113	  knownDegustLojaIds: ReadonlySet<number>,
1114	): FlashRow[] {
1115	  const out: FlashRow[] = [];
1116	  for (const row of rows) {
1117	    if (knownDegustLojaIds.has(row.loja_id)) {
1118	      out.push(row);
1119	      continue;
1120	    }
1121	    const mapped = degustCodeToLoja.get(row.loja_id);
1122	    if (mapped != null) {
1123	      out.push({ ...row, loja_id: mapped });
1124	    }
1125	    // não mapeável → descartado de propósito (ver TSDoc)
1126	  }
1127	  return out;
1128	}
