1130	/**
1131	 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
1132	 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
1133	 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
1134	 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
1135	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
1136	 * o drill-down, a lista completa.
1137	 */
1138	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
1139	  const missingFraction = (c: TvCriticalItem): number =>
1140	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
1141	  return items
1142	    .map<TvCriticalItem>((i) => ({
1143	      nome: i.produtoNome,
1144	      quantidade: i.quantidade,
1145	      minima: i.quantidadeMinima,
1146	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
1147	    }))
1148	    .sort((a, b) => {
1149	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
1150	      const diff = missingFraction(b) - missingFraction(a);
1151	      if (diff !== 0) return diff;
1152	      return a.nome.localeCompare(b.nome, 'pt-BR');
1153	    });
1154	}
