1288	
1289	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
1290	export interface TvPageResult<T> {
1291	  data: T[] | null;
1292	  error: { message: string } | null;
1293	}
1294	
1295	/**
1296	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
1297	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
1298	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
1299	 *
1300	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
1301	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
1302	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
1303	 * sobreporem entre requests.
1304	 */
1305	export async function fetchAllPages<T>(
1306	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
1307	  pageSize = 1000,
1308	): Promise<T[]> {
1309	  const all: T[] = [];
1310	  let offset = 0;
1311	  for (;;) {
1312	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
1313	    if (error) throw error;
1314	    const rows = data ?? [];
1315	    all.push(...rows);
1316	    if (rows.length < pageSize) return all;
1317	    offset += pageSize;
1318	  }
1319	}
