/**
 * Parser do `ultima_atualizacao` do flash-vendas Degust, cujo formato de
 * data DEPENDE da culture do servidor da API: historicamente chegava como
 * "DD/MM/YYYY HH:mm:ss" (pt-BR), mas em 2026-06-12 o payload real veio
 * "06/12/2026 13:17:00" — MM/DD/YYYY (en-US). Ler cegamente como DD/MM
 * jogava o flash pra 6/dez e o gate da virada do dia zerava TODOS os cards.
 *
 * Estratégia: gera as DUAS interpretações ("A/B" como dia/mês E como
 * mês/dia, descartando inválidas — mês 13, 31/02 etc.) e escolhe a que cai
 * na janela plausível [now−3d, now+1d]: flash é dado quase-live, nunca está
 * a semanas do relógio. As duas leituras distam ≥28 dias entre si, então no
 * máximo UMA cai na janela — exceto quando A === B (são idênticas). Se
 * nenhuma cair (dado muito stale), devolve a mais próxima de `now`: data
 * parseável porém velha é problema de FRESHNESS, não de parsing. Sem
 * leitura válida → null.
 */
export function parseDegustFlashDateTime(
  raw: string | null | undefined,
  now: Date,
): Date | null {
  if (!raw) return null;
  const m = raw.match(
    /^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/,
  );
  if (!m) return null;
  const [, aStr, bStr, yyyy, hh, mi, ss] = m;
  const a = Number(aStr);
  const b = Number(bStr);
  const build = (day: number, month: number): Date | null => {
    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
    const d = new Date(
      Number(yyyy),
      month - 1,
      day,
      Number(hh),
      Number(mi),
      ss ? Number(ss) : 0,
    );
    // Overflow de dia no mês (31/02 → vira 03/03) = leitura inválida
    if (d.getMonth() !== month - 1 || d.getDate() !== day) return null;
    return d;
  };

  const candidates: Date[] = [];
  const asDdMm = build(a, b);
  if (asDdMm) candidates.push(asDdMm);
  if (a !== b) {
    const asMmDd = build(b, a);
    if (asMmDd) candidates.push(asMmDd);
  }
  if (candidates.length === 0) return null;

  const DAY_MS = 86_400_000;
  const inWindow = candidates.filter(
    (d) =>
      d.getTime() >= now.getTime() - 3 * DAY_MS &&
      d.getTime() <= now.getTime() + DAY_MS,
  );
  const pool = inWindow.length > 0 ? inWindow : candidates;
  return pool.reduce((best, d) =>
    Math.abs(d.getTime() - now.getTime()) <
    Math.abs(best.getTime() - now.getTime())
      ? d
      : best,
  );
}

