describe('parseDegustFlashDateTime (data ambígua MM/DD vs DD/MM da API Degust)', () => {
  const noon = (y: number, m0: number, d: number) =>
    new Date(y, m0, d, 12, 0, 0);

  it('payload MM/DD real ("06/12/2026") com now em 12/jun → 12 de junho', () => {
    // Caso do bug de produção 2026-06-12: lido como DD/MM virava 6/dez e o
    // gate da virada do dia zerava todos os cards.
    const d = parseDegustFlashDateTime(
      '06/12/2026 13:17:00',
      noon(2026, 5, 12),
    );
    expect(d?.getFullYear()).toBe(2026);
    expect(d?.getMonth()).toBe(5); // junho
    expect(d?.getDate()).toBe(12);
    expect(d?.getHours()).toBe(13);
    expect(d?.getMinutes()).toBe(17);
  });

  it('payload DD/MM ("12/06/2026") com now em 12/jun → TAMBÉM 12 de junho', () => {
    // Leitura DD/MM cai na janela; a MM/DD (6/dez) fica fora — escolhe DD/MM.
    const d = parseDegustFlashDateTime(
      '12/06/2026 13:17:00',
      noon(2026, 5, 12),
    );
    expect(d?.getMonth()).toBe(5);
    expect(d?.getDate()).toBe(12);
    expect(d?.getHours()).toBe(13);
  });

  it('dia > 12 desambigua sozinho: "31/12/2026" com now 01/jan/2027 → 31/dez (MM/DD seria mês 31, inválido)', () => {
    const d = parseDegustFlashDateTime(
      '31/12/2026 23:59:00',
      noon(2027, 0, 1),
    );
    expect(d?.getFullYear()).toBe(2026);
    expect(d?.getMonth()).toBe(11);
    expect(d?.getDate()).toBe(31);
    expect(d?.getHours()).toBe(23);
    expect(d?.getMinutes()).toBe(59);
  });

  it('única leitura válida fora da janela (dado stale) → ainda retorna a data (staleness é outra camada)', () => {
    // 29/05 DD/MM é válido porém 14 dias atrás; MM/DD seria mês 29 (inválido).
    const d = parseDegustFlashDateTime(
      '29/05/2026 10:00:00',
      noon(2026, 5, 12),
    );
    expect(d?.getMonth()).toBe(4); // maio
    expect(d?.getDate()).toBe(29);
  });

  it('entrada inválida/ausente → null', () => {
    const now = noon(2026, 5, 12);
    expect(parseDegustFlashDateTime('not-a-date', now)).toBeNull();
    expect(parseDegustFlashDateTime('13/13/2026 10:00:00', now)).toBeNull();
    // 31/02 estoura o mês nas duas leituras (DD/MM overflow; MM/DD mês 31)
    expect(parseDegustFlashDateTime('31/02/2026 10:00:00', now)).toBeNull();
    expect(parseDegustFlashDateTime(null, now)).toBeNull();
    expect(parseDegustFlashDateTime(undefined, now)).toBeNull();
    expect(parseDegustFlashDateTime('', now)).toBeNull();
  });
});

